          "În Base: Forms > Use Wizard to Create Form",
          "Selectează tabelul 'Carti' ca sursa",
          "Alege campurile: Titlu, Autor, An_Publicare, Disponibila",
          "Alege layout: Columnar (un camp sub altul)",
          "Alege un stil/tema",
          "Denumeste formularul: 'Formular_Carti'"
        ],
        "teacher_support": "Parcurgeti Wizard-ul pe proiector, asteptati la fiecare pas"
      },
      {
        "task": "Utilizarea formularului",
        "steps": [
          "Deschide formularul creat",
          "Observa butoanele de navigare din partea de jos",
          "Navigheaza între inregistrari folosind sagetile",
          "Găsește butonul pentru înregistrare noua (New Record)",
          "Adaugă o carte noua folosind formularul",
          "Observa ca datele apar automat în tabel"
        ],
        "teacher_support": "Subliniati conexiunea formular-tabel: sunt aceleasi date"
      },
      {
        "task": "Personalizare de baza în Design View",
        "steps": [
          "Click dreapta pe formular > Design View",
          "Observa structura: secțiuni Header, Detail, Footer",
          "Click pe o eticheta și modifică textul (ex: 'Titlu carte:' în loc de 'Titlu')",
          "Selectează un TextBox și redimensionează-l",
          "Adaugă un titlu în Header: 'Biblioteca - Adaugare Carti'",
          "Salvează și testeaza formularul"
        ],
        "teacher_support": "Demonstrati selectarea și modificarea controalelor"
      }
    ],
    "success_criteria": [
      "Elevul a creat un formular functional cu Form Wizard",
      "Elevul poate naviga între inregistrari în formular",
      "Elevul a adaugat o înregistrare noua prin formular",
      "Elevul a personalizat cel putin o eticheta sau un titlu"
    ]
  },
  "practice_independent": {
    "duration_minutes": 12,
    "levels": {
      "minim": [
        {
          "task": "Creaza un formular pentru tabelul 'Cititori' (dacă există) sau pentru alt tabel. Folosește Form Wizard și adaugă o înregistrare noua prin formular.",
          "expected_output": "Formular functional pentru alt tabel, cu o înregistrare noua adaugata"
        }
      ],
      "standard": [
        {
          "task": "Personalizează formularul 'Formular_Carti': modifică toate etichetele să fie mai descriptive, adaugă un titlu în header, schimbă culorile de fundal. Testeaza adaugarea a 2 carti noi.",
          "expected_output": "Formular personalizat vizual, functional, cu 2 inregistrari noi"
        }
      ],
      "performanta": [
        {
          "task": "Creaza un formular de la zero în Design View (fara Wizard). Adaugă manual controalele pentru fiecare camp, etichetele corespunzătoare și un titlu. Exploreaza adaugarea unui buton de navigare.",
          "expected_output": "Formular creat manual în Design View, functional și organizat"
        }
      ]
    }
  },
  "wrap_up": {
    "duration_minutes": 7,
    "exit_ticket": {
      "minim": [
        "Ce avantaj are un formular față de editarea directa în tabel?"
      ],
      "standard": [
        "Numește 3 tipuri de controale dintr-un formular și explică rolul fiecaruia."
      ],
      "performanta": [
        "Dacă ar trebui să creezi un formular pentru o clinica medicala, ce masuri ai lua pentru protectia datelor sensibile ale pacientilor?"
      ]
    },
    "preview_next": "Saptamana viitoare învățăm să cream rapoarte - documente tiparibile cu datele organizate frumos, perfecte pentru prezentare sau arhivare!"
  }
